style.css:
@-moz-document domain("google.com") {
/* BACKGROUND IMAGE */
body {

    background-image:
    url("https://i.pinimg.com/1200x/4e/ea/55/4eea55f530badfb5a942eb1984a4ea6e.jpg") !important;

    background-size:cover !important;

    background-position:center !important;

    background-attachment:fixed !important;

    background-repeat:no-repeat !important;
}


/* REMOVE GOOGLE WHITE BACKGROUND */

#searchform,
#rcnt,
#main,
#center_col,
#rhs {

    background:transparent!important;
}


/* GOOGLE LOGO AREA */

#lga {

    filter:
    drop-shadow(0 0 10px #ffb6d6);
}


/* SEARCH BOX */

.RNNXgb {

    background:
    linear-gradient(
        90deg,
        rgba(255,225,240,.9),
        rgba(220,245,255,.9)
    ) !important;


    border-radius:30px!important;

    border:2px solid #f5b7d2!important;

    backdrop-filter:blur(12px);

    box-shadow:
    0 0 15px rgba(255,180,210,.4);
}


/* SEARCH TEXT */

input {

    color:#c85b8c!important;

}


input::placeholder {

    color:#c85b8c!important;

}


/* SEARCH BUTTONS */

input[type="submit"],
button {

    background:
    linear-gradient(
        90deg,
        #ffd1e5,
        #cdefff
    ) !important;


    color:#c85b8c!important;

    border-radius:25px!important;

    border:none!important;

}


/* SEARCH RESULTS */

#search .g {

    background:
    rgba(255,255,255,.65)!important;

    backdrop-filter:blur(10px);

    border-radius:18px;

    padding:15px;

    box-shadow:
    0 5px 20px rgba(255,160,200,.25);
}


/* RESULT TITLES */

h3,
a {

    color:#c85b8c!important;

}


/* NORMAL TEXT */

span,
div {

    color:#b85a83;
}


/* GOOGLE MENUS */

[role="menu"],
[role="dialog"] {

    background:
    linear-gradient(
        180deg,
        #ffe3ef,
        #dff5ff
    )!important;

    border-radius:20px!important;

}


/* SCROLLBAR */

::-webkit-scrollbar {

    width:10px;

}


::-webkit-scrollbar-thumb {

    background:
    linear-gradient(
        #ffb6d6,
        #a9e4ff
    );

    border-radius:20px;

}


/* HOVER GLOW */

button:hover,
.RNNXgb:hover {

    box-shadow:

    0 0 12px #ffb6d6,

    0 0 20px #a9e4ff;

}
}
